def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 8):
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    is_solution = S_N == T_N
    results[N] = (S_N, T_N, is_solution)

print("N | S(N) | T(N) | Match")
for N, (S_N, T_N, match) in results.items():
    print(f"{N} | {S_N} | {T_N} | {match}")

